#include "jd_protocol.h"

#if JD_PHYSICAL

// Enabling logging can cause delays and dropped packets!
// #define LOG JD_LOG
#define LOG JD_NOLOG

#define JD_STATUS_RX_ACTIVE 0x01
#define JD_STATUS_TX_ACTIVE 0x02
#define JD_STATUS_TX_QUEUED 0x04

extern volatile uint32_t g_app_jd_diag_rx_complete;
extern volatile uint32_t g_app_jd_diag_crc_ok;
extern volatile uint16_t g_app_jd_line_fall_handler_entry_tick;
extern volatile uint16_t g_app_jd_line_fall_after_wait_high_tick;
uint16_t app_jacdac_diag_tick_now(void);

enum {
    APP_JD_RX_DIAG_RING_SIZE = 4,
    APP_JD_RX_DIAG_RAW_BYTES = 16,

    APP_JD_RX_DIAG_REASON_UNKNOWN = 0,
    APP_JD_RX_DIAG_REASON_SIZE_ZERO = 1,
    APP_JD_RX_DIAG_REASON_DATA_LEFT_NEGATIVE = 2,
    APP_JD_RX_DIAG_REASON_SHORT_FRAME = 3,
    APP_JD_RX_DIAG_REASON_CRC_ERROR = 4,
    APP_JD_RX_DIAG_REASON_BAD_SIZE = 5,
    APP_JD_RX_DIAG_REASON_VNEXT = 6,
    APP_JD_RX_DIAG_REASON_RX_QUEUE_DROP = 7,
    APP_JD_RX_DIAG_REASON_OK = 8,
    APP_JD_RX_DIAG_REASON_MAX = 9,
};

struct _app_jd_rx_diag_record_t {
    uint32_t seq;
    int32_t data_left;
    uint32_t tx_size;
    uint32_t declared_size;
    uint16_t calc_crc;
    uint16_t frame_crc;
    uint8_t frame_size;
    uint8_t flags;
    uint8_t service_size;
    uint8_t service_index;
    uint16_t service_command;
    uint8_t reason;
    uint8_t raw_len;
    uint8_t raw[APP_JD_RX_DIAG_RAW_BYTES];
} __attribute__((__packed__, aligned(4)));
typedef struct _app_jd_rx_diag_record_t app_jd_rx_diag_record_t;

volatile uint32_t g_app_jd_rx_diag_ring_head;
volatile uint32_t g_app_jd_rx_diag_seq;
volatile uint32_t g_app_jd_rx_diag_last_reason;
volatile uint32_t g_app_jd_rx_diag_reason_counts[APP_JD_RX_DIAG_REASON_MAX];
volatile app_jd_rx_diag_record_t g_app_jd_rx_diag_ring[APP_JD_RX_DIAG_RING_SIZE];

static jd_frame_t rxFrame;
static void set_tick_timer(uint8_t statusClear);
static volatile uint8_t phys_status;

static jd_frame_t *txFrame;
static uint64_t nextAnnounce;
static uint8_t txPending;

static jd_diagnostics_t jd_diagnostics;

jd_diagnostics_t *jd_get_diagnostics(void) {
    jd_diagnostics.bus_state = 0; // TODO?
    return &jd_diagnostics;
}

int jd_is_running(void) {
    return nextAnnounce != 0;
}

int jd_is_busy(void) {
    return phys_status != 0;
}

static void tx_done(void) {
    jd_debug_signal_write(0);
    set_tick_timer(JD_STATUS_TX_ACTIVE);
}

void jd_tx_completed(int errCode) {
    LOG("tx done: %d", errCode);
    jd_tx_frame_sent(txFrame);
    txFrame = NULL;
    tx_done();
}

static uint32_t start_tx;
static void tick(void) {
    if (phys_status & JD_STATUS_TX_ACTIVE) {
        uint32_t d = tim_get_micros() - start_tx;
        // this can get delayed when we block interrupts for a long time (eg during flashing)
        // but we don't want it to take forever; give it 130ms
        if (d > 0x20000) {
            JD_DMESG("TX fail; %u us", (unsigned)d);
            JD_PANIC();
        }
    }
    set_tick_timer(0);
}

static void flush_tx_queue(void) {
    LOG("flush %d", phys_status);
    target_disable_irq();
    if (phys_status & (JD_STATUS_RX_ACTIVE | JD_STATUS_TX_ACTIVE)) {
        target_enable_irq();
        return;
    }
    phys_status |= JD_STATUS_TX_ACTIVE;
    target_enable_irq();

    txPending = 0;
    if (!txFrame) {
        txFrame = jd_tx_get_frame();
        if (!txFrame) {
            tx_done();
            return;
        }
    }

    jd_debug_signal_write(1);

    start_tx = tim_get_micros();

    if (uart_start_tx(txFrame, JD_FRAME_SIZE(txFrame)) < 0) {
        // ERROR("race on TX");
        jd_diagnostics.bus_lo_error++;
        tx_done();
        txPending = 1;
        return;
    }

    set_tick_timer(0);
}

static void set_tick_timer(uint8_t statusClear) {
    target_disable_irq();
    if (statusClear) {
        // LOG("st %d @%d", statusClear, phys_status);
        phys_status &= ~statusClear;
    }
    if ((phys_status & JD_STATUS_RX_ACTIVE) == 0) {
        if (txPending && !(phys_status & JD_STATUS_TX_ACTIVE)) {
            // the JD_WR_OVERHEAD value should be such, that the time from pulse1() above
            // to beginning of low-pulse generated by the current device is exactly 150us
            // (when the line below is uncommented)
            // tim_set_timer(150 - JD_WR_OVERHEAD, flush_tx_queue);
            phys_status |= JD_STATUS_TX_QUEUED;
            tim_set_timer(jd_random_around(150) - JD_WR_OVERHEAD, flush_tx_queue);
        } else {
            phys_status &= ~JD_STATUS_TX_QUEUED;
            tim_set_timer(JD_MIN_MAX_SLEEP, tick);
        }
    }
    target_enable_irq();
}

static void rx_timeout(void) {
    target_disable_irq();
    jd_diagnostics.bus_timeout_error++;
    LINE_ERROR("RX t/o");
    uart_disable();
    jd_debug_signal_read(0);
    set_tick_timer(JD_STATUS_RX_ACTIVE);
    target_enable_irq();
}

static void setup_rx_timeout(void) {
    target_disable_irq();
    // It's possible this only gets executed after the entire reception process has finished.
    // In that case, we don't want to set the rx_timeout().
    if (phys_status & JD_STATUS_RX_ACTIVE) {
        uart_flush_rx();
        uint32_t *p = (uint32_t *)&rxFrame;
        if (p[0] == 0 && p[1] == 0) {
            rx_timeout(); // didn't get any data after lo-pulse
        } else {
            // got the size - set timeout for whole packet
            tim_set_timer(JD_FRAME_SIZE(&rxFrame) * 12 + 60, rx_timeout);
        }
    } else {
        set_tick_timer(0);
    }
    target_enable_irq();
}

static void app_jd_rx_diag_store(jd_frame_t *frame, int dataLeft, uint32_t txSize, uint32_t declaredSize,
                                 uint16_t calcCrc, uint8_t reason) {
    uint32_t i;
    uint32_t rawLen = txSize;
    uint32_t head = g_app_jd_rx_diag_ring_head;
    volatile app_jd_rx_diag_record_t *rec = &g_app_jd_rx_diag_ring[head % APP_JD_RX_DIAG_RING_SIZE];
    const uint8_t *raw = (const uint8_t *)frame;

    if (rawLen > APP_JD_RX_DIAG_RAW_BYTES)
        rawLen = APP_JD_RX_DIAG_RAW_BYTES;

    rec->seq = ++g_app_jd_rx_diag_seq;
    rec->data_left = dataLeft;
    rec->tx_size = txSize;
    rec->declared_size = declaredSize;
    rec->calc_crc = calcCrc;
    rec->frame_crc = frame->crc;
    rec->frame_size = frame->size;
    rec->flags = frame->flags;
    rec->service_size = txSize >= JD_SERIAL_FULL_HEADER_SIZE ? ((jd_packet_t *)frame)->service_size : 0;
    rec->service_index = txSize >= JD_SERIAL_FULL_HEADER_SIZE ? ((jd_packet_t *)frame)->service_index : 0;
    rec->service_command = txSize >= JD_SERIAL_FULL_HEADER_SIZE ? ((jd_packet_t *)frame)->service_command : 0;
    rec->reason = reason;
    rec->raw_len = (uint8_t)rawLen;

    for (i = 0; i < APP_JD_RX_DIAG_RAW_BYTES; ++i)
        rec->raw[i] = i < rawLen ? raw[i] : 0;

    g_app_jd_rx_diag_last_reason = reason;
    if (reason < APP_JD_RX_DIAG_REASON_MAX)
        g_app_jd_rx_diag_reason_counts[reason]++;
    g_app_jd_rx_diag_ring_head = head + 1;
}

void jd_line_falling(void) {
    LOG("line fall");

    g_app_jd_line_fall_handler_entry_tick = app_jacdac_diag_tick_now();

    jd_debug_signal_read(1);

    // target_disable_irq();
    // no need to disable IRQ - we're at the highest IRQ level
    if (phys_status & JD_STATUS_RX_ACTIVE)
        JD_PANIC();
    phys_status |= JD_STATUS_RX_ACTIVE;

    // 1us faster than memset() on SAMD21
    uint32_t *p = (uint32_t *)&rxFrame;
    p[0] = 0;
    p[1] = 0;
    p[2] = 0;
    p[3] = 0;

    // otherwise we can enable RX in the middle of LO pulse
    if (uart_wait_high() < 0) {
        // line didn't get high in 1ms or so - bail out
        rx_timeout();
        return;
    }
    g_app_jd_line_fall_after_wait_high_tick = app_jacdac_diag_tick_now();
    // pulse1();
    // target_wait_us(2);

    uart_start_rx(&rxFrame, sizeof(rxFrame));
    // log_pin_set(1, 0);

    // 200us max delay according to spec, +50us to get the first 4 bytes of data
    // phys_status might be missing JD_STATUS_RX_ACTIVE in case it finished real quick
    if (phys_status & JD_STATUS_RX_ACTIVE)
        tim_set_timer(250, setup_rx_timeout);

    // target_enable_irq();
}

void jd_rx_completed(int dataLeft) {
    LOG("rx cmpl");
    jd_frame_t *frame = &rxFrame;
    uint32_t txSize = 0;
    uint32_t declaredSize = JD_FRAME_SIZE(frame);
    uint16_t crc = 0;

    g_app_jd_diag_rx_complete++;

    jd_debug_signal_read(0);

    set_tick_timer(JD_STATUS_RX_ACTIVE);

    if (dataLeft >= 0 && (uint32_t)dataLeft <= sizeof(*frame))
        txSize = sizeof(*frame) - (uint32_t)dataLeft;

    if (frame->size == 0) {
        // TODO we can't report it, since it happens *very often* when line is held down on ESP32
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, 0, APP_JD_RX_DIAG_REASON_SIZE_ZERO);
        return;
    }

    if (dataLeft < 0) {
        LINE_ERROR("rx err: %d", dataLeft);
        jd_diagnostics.bus_uart_error++;
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, 0, APP_JD_RX_DIAG_REASON_DATA_LEFT_NEGATIVE);
        return;
    }

    if (txSize < declaredSize) {
        LINE_ERROR("short frm");
        jd_diagnostics.bus_uart_error++;
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, 0, APP_JD_RX_DIAG_REASON_SHORT_FRAME);
        return;
    }

    crc = jd_crc16((uint8_t *)frame + 2, declaredSize - 2);
    if (crc != frame->crc) {
        LINE_ERROR("crc err");
        jd_diagnostics.bus_uart_error++;
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, crc, APP_JD_RX_DIAG_REASON_CRC_ERROR);
        return;
    }
    g_app_jd_diag_crc_ok++;

    if (declaredSize > JD_SERIAL_PAYLOAD_SIZE + JD_SERIAL_FULL_HEADER_SIZE ||
        ((jd_packet_t *)frame)->service_size > JD_SERIAL_PAYLOAD_SIZE) {
        LINE_ERROR("bad size");
        jd_diagnostics.bus_uart_error++;
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, crc, APP_JD_RX_DIAG_REASON_BAD_SIZE);
        return;
    }

    if (frame->flags & JD_FRAME_FLAG_VNEXT) {
        jd_diagnostics.packets_dropped++;
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, crc, APP_JD_RX_DIAG_REASON_VNEXT);
        return;
    }

    jd_diagnostics.packets_received++;

    // pulse1();
    int err = jd_rx_frame_received(frame);

    if (err) {
        LINE_ERROR("drop RX");
        jd_diagnostics.packets_dropped++;
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, crc, APP_JD_RX_DIAG_REASON_RX_QUEUE_DROP);
    } else {
        app_jd_rx_diag_store(frame, dataLeft, txSize, declaredSize, crc, APP_JD_RX_DIAG_REASON_OK);
    }
}

void jd_packet_ready(void) {
    target_disable_irq();
    txPending = 1;
    if (phys_status == 0)
        set_tick_timer(0);
    target_enable_irq();
}

void _jd_phys_start(void) {
    set_tick_timer(0);
}

#endif
